<template>
  <div class="container" v-loading="loading">
    <div class="vote_add_top" @click="return_vote_list_add">
      <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回列表
    </div>
    <div class="box-limit">
      <div class="container-box">
        <div class="editbox">
          <!-- 标题 -->
          <div class="title">
            <input type="text"   v-model="template_title" :placeholder="template_title_placeholder" class="title_box" @focus="focus_title" @blur="blur_title"/>
          </div>

          <!-- 副标题添加图片 -->
          <div class="add_background_img align-icon" @click="up_img">
            <el-row class="up-img-box">
              <el-col :span="2"><div class="align-up-img"></div></el-col>
              <el-col :span="22" class="img_tip">&nbsp;上传背景图片(建议尺寸2480*3508)</el-col>
            </el-row>
          </div>
          <input accept="image/*" type="file" name="file" ref="tempUploadFile" v-on:change="uploadPic" style="display: none;"/>


          <div class="list" id="list" :style="{'font-size':'14px',backgroundImage: template_img, width: template_width, backgroundSize : '100% auto', backgroundRepeat: 'no-repeat'}">
            <img :src="template_img_box" ref="template_img_box_display" :style="{width: template_width, 'height': 'auto'}">
            <VueDragResize v-for="(rect, index) in rects"
                          :key="index"
                          :w="rect.width"
                          :h="rect.height"
                          :x="rect.left"
                          :y="rect.top"
                          :parentW="listWidth"
                          :parentH="listHeight"
                          :isActive="rect.active=='1'"
                          :minw="rect.minw"
                          :minh="rect.minh"
                          :isDraggable="rect.draggable=='1'"
                          :isResizable="rect.resizable=='1'"
                          :parentLimitation="rect.parentLim=='1'"
                          :z="rect.zIndex"
                          v-on:activated="activateEv(index)"
                          v-on:deactivated="deactivateEv(index)"
                          v-on:dragging="resize($event, index)"
                          v-on:resizing="resize($event, index)"
            >
              <div class="filler" ref="filler_div_box" :style="{backgroundColor:rect.backgroundColor,color:rect.color, lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                {{rect['type_text']}}
              </div>
              <div class="close_block" v-if="rect.is_close=='1'" @click="close_block(index)" :style="{'z-index':rect.zIndex+1}">×</div>
            </VueDragResize>
          </div>


        </div>




        <div class="add">
          <div class="addbox">
            <div class="addtext">请选择对应选框</div>
            <div class="addbtn">
              <el-row v-for="(item,key) in add_material_btn" :key="key">
                  <el-button size="small" @click="add_tip(key)">{{item}}</el-button>
              </el-row>
            </div>
          </div>
          <div>
            <el-button type="primary" style="width:270px;margin-top:40px" @click="finish_vote">完成创建</el-button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
  import VueDragResize from 'vue-drag-resize'
  export default {
    name: 'add_template',
    components: {
      VueDragResize
    },
    data() {
      return {
        template_img: '',
        template_img_box: '',
        template_width: '800px',
        listWidth: 0,
        listHeight: 0,
        zIndexMax: 1,
        rects: [],
        template_img_val: '', // 上传的背景图片
        template_title: '', // 模板标题
        tip_info: [
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'title_txt',
            'type_text': '标题文本',
            'is_close': '0'
          },
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'txt',
            'type_text': '单行文本',
            'is_close': '0'
          },
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'mul_txt',
            'type_text': '多行文本',
            'is_close': '0'
          },
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'floor_choose',
            'type_text': '单元选择框',
            'is_close': '0'
          },
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'owner_choose',
            'type_text': '业主姓名选择框',
            'is_close': '0'
          },
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'owner_phone',
            'type_text': '业主联系方式框',
            'is_close': '0'
          },
          {
            'width': 120,
            'height': 30,
            'top': 20,
            'left': 340,
            'draggable': '1',
            'resizable': '1',
            'minw': 60,
            'minh': 20,
            'axis': 'both',
            'parentLim': '1',
            'zIndex': 1,
            'backgroundColor': '#2681F3',
            'color': '#ffffff',
            'active': '0',
            'type': 'date_choose',
            'type_text': '日期选择框',
            'is_close': '0'
          }
        ],
        add_material_btn: [
          '标题文本',
          '单行文本',
          '多行文本',
          '单元选择框',
          '业主姓名选择框',
          '业主联系方式框',
          '时间选择框',
        ],
        loading: false,
        template_id: '',
        template_title_placeholder: '请输入模板标题',
        is_click: false,
        key_num: 0,
        del_index: -1
      }
    },
    created () {
      this.template_id = this.$route.query.template_id;
      if (this.template_id>0) {
        let param = {};
        param['template_id'] = this.template_id;
        this.templateDetail(param);
      }
      this.templateConfig();
    },
    mounted() {
      console.log('mounted');
      let listEl = document.getElementById('list');
      // console.log('clientWidth',listEl.clientWidth);
      this.listWidth = listEl.clientWidth;
      this.listHeight = this.$refs.template_img_box_display.clientHeight;
      // window.addEventListener('resize', ()=>{
      //   this.listWidth = listEl.clientWidth;
      //   // this.listHeight = listEl.clientHeight;
      //   this.listHeight = this.$refs.template_img_box_display.clientHeight;
      // })
    },
    methods: {
      reload() {
        this.listHeight = this.$refs.template_img_box_display.clientHeight;
      },
      return_vote_list_add: function () {
        this.$router.replace({ path: '/template_list'});
      },
      resize(newRect, index) {
        console.log('index',index);
        if (this['rects'][index]['zIndex']<this.zIndexMax) {
          this.zIndexMax++;
        }
        this['rects'][index]['width'] = newRect.width;
        this['rects'][index]['height'] = newRect.height;
        this['rects'][index]['top'] = newRect.top;
        this['rects'][index]['left'] = newRect.left;
        this['rects'][index]['zIndex'] = this.zIndexMax;
      },
      activateEv(index) {
        console.log('activateEv',index);
        this['rects'][index]['active'] = true;
        this['rects'][index]['is_close'] = true;
      },
      deactivateEv(index) {
        console.log('deactivateEv',index);
        console.log('del_index',this.del_index);
        if (this.del_index==index) {
          this.del_index = -1;
        } else {
          this['rects'][index]['is_close'] = false;
          this['rects'][index]['active'] = false;
        }
      },
      close_block(index) {
        let rects = JSON.parse(JSON.stringify(this.rects));
        let val = [];
        for(let i in rects) {
          if (rects[i] && i!=index) {
            val.push(rects[i]);
          }
        }
        this.del_index = index;
        // rects.splice(index,1);
        this.rects = val;
        console.log('rects',rects);
        console.log('rects1',this.rects);
        // this.$forceUpdate();
        var that = this;
        var len = rects.length - 1;
        if (index<len) {
          setTimeout(function () {
            var nodes = that.$refs.filler_div_box[index].parentElement;
            nodes.style.left = val[index].left +'px';
            nodes.style.top = val[index].top +'px';
          },0);
        }
      },
      uploadPic(e) {
          console.log('e', e);
        let _self = this;
        let inputFile = e.target;
        if (!inputFile.files || inputFile.files.length <= 0) {
          return;
        }
        let file_msg = inputFile.files[0];
          console.log('file_msg', file_msg)
        let formData = new FormData()
        formData.append('file', file_msg)
        this.loading = true;
        this.ajaxUploadPic(formData)
      },
      // 获取配置
      async templateConfig() {
        let res = await this.$api.templateConfig();
        if (res) {
          console.log(`templateConfig: `, res);
          if (res.add_material_btn) {
            this.add_material_btn = res.add_material_btn;
          }
          if (res.template_tip) {
            this.tip_info = res.template_tip;
          }
        }
      },
      // 上传图片
      async ajaxUploadPic(param) {
        let res = await this.$api.ajaxUploadPic(param);
        if (res) {
          console.log(`ajaxUploadPic: `, res);
          this.template_img = 'url('+res.file_url+')';
          this.template_img_val = res.url;
          this.template_img_box = res.file_url;
          let that = this;
          setTimeout(function () {
            that.reload();
          },800);
        }
        this.loading = false;
      },
      // 获取详情
      async templateDetail(param) {
        let res = await this.$api.templateDetail(param);
        if (res) {
          console.log(`templateDetail: `, res);
          this.rects = JSON.parse(JSON.stringify(res.template_content));
          this.template_title = res.template_title;
          this.template_img_val = res.template_img;
          this.template_img = 'url('+res.template_img_path+')';
          this.template_img_box = res.template_img_path;
          if (res.template_width) {
            this.template_width = res.template_width;
          }
          if (res.zIndexMax) {
            this.zIndexMax = res.zIndexMax;
          }
          let that = this;
          setTimeout(function () {
            that.reload();
          },800);
        }
      },
      // 编辑
      async editTemplate(param) {
        let res = await this.$api.editTemplate(param);
        let _this=this;
        if (res) {
          this.$message({
            type: 'success',
            message: '修改成功!'
          });
          _this.$router.replace({ path: '/template_list'});
        } else if (res.errorMsg) {
          this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      // 添加
      async addTemplate(param) {
        let res = await this.$api.addTemplate(param);
        let _this=this;
        if (res) {
          this.$message({
            type: 'success',
            message: '添加成功!'
          });
        } else if (res.errorMsg) {
          this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        _this.$router.replace({ path: '/template_list'});
        return res;
      },
      finish_vote: function(e) {
        console.log('rects结果：',this.rects);
        console.log('template_img_val结果：',this.template_img_val);
        console.log('template_title结果：',this.template_title);
        if (!this.template_title) {
          console.log('err：',1);
          this.$message({
            message: '请输入模板标题',
            type: 'warning'
          });
          return false;
        }
        if (!this.template_img_val) {
          this.$message({
            message: '请上传背景图片',
            type: 'warning'
          });
          return false;
        }
        if (!this.rects) {
          this.$message({
            message: '最少选择一个选框',
            type: 'warning'
          });
          return false;
        }
        let rects = this.rects;
        let param = {};
        param['template_content'] = this.rects;
        param['template_img'] = this.template_img_val;
        param['template_title'] = this.template_title;
        param['template_width'] = this.template_width;
        console.log('param：',param);
        if (this.template_id && this.template_id>0) {
          param['template_id'] = this.template_id;
          this.editTemplate(param);
        } else {
          this.addTemplate(param);
        }
      },
      add_tip(index) {
        if (!this.template_img_val) {
          this.$message({
            message: '请先上传背景图片',
            type: 'warning'
          });
          return false;
        }
        let key_num = this.key_num;
        let msg = JSON.parse(JSON.stringify(this.tip_info[index]));
        if (msg['zIndex']<this.zIndexMax) {
          this.zIndexMax++;
        }
        msg['key_num'] = key_num;
        msg['zIndex'] = this.zIndexMax;
        msg['active'] = true;
        msg['is_close'] = true;
        this.key_num++;
        console.log('msg',msg);
        this.rects.push(msg);
        console.log('rects',this.rects);
      },
      up_img: function() {
        console.log('触发上传图片')
        this.$refs.tempUploadFile.click();
      },
      focus_title(e) {
        console.log('focus_title')
        if(e.target && this.vote_title_placeholder){
          this.vote_title_placeholder = '';
        }
      },
      blur_title(e) {
        console.log('blur_title')
        if(e.target && !this.vote_title_placeholder){
          this.vote_title_placeholder = '请输入表单标题';
        }
      }
    }
  }
</script>

